-- Growths — Escola Aurora · PARTE 2 de 4: imagens dos criativos (12 anúncios). Rode depois da parte 1. Pode rodar de novo.
update anuncios a set imagem_url = x.img from (values
('AD01 · Trava na hora de falar · Estático','data:image/webp;base64,'),
('AD04 · 3 erros de quem estuda sozinho · Carrossel','data:image/webp;base64,'),
('AD07 · Viajar sem medo · Reels','data:image/webp;base64,'),
('AD10 · Trava na hora de falar · Estático','data:image/webp;base64,'),
('AD13 · Promoção no trabalho · Estático','data:image/webp;base64,'),
('AD16 · Trava na hora de falar · Estático','data:image/webp;base64,'),
('AD19 · Você fala “I am agree”? · Estático','data:image/webp;base64,'),
('AD22 · Garanta sua vaga · Estático','data:image/webp;base64,'),
('AD25 · Vídeo 30s · Depoimento Carla · Vídeo','data:image/webp;base64,'),
('AD28 · Busca · inglês rápido · Texto','data:image/webp;base64,'),
('AD31 · Fala comigo em inglês · Vertical','data:image/webp;base64,'),
('Perpétuo · Oferta do curso','data:image/webp;base64,')
) x(nome, img), workspaces w
where w.nome = 'Escola Aurora' and a.workspace_id = w.id and a.nome = x.nome;
select count(*) filter (where a.imagem_url is not null) as anuncios_com_imagem, count(*) as anuncios from anuncios a join workspaces w on w.id = a.workspace_id where w.nome = 'Escola Aurora';
